package main

import (
	"encoding/base64"
	"fmt"
	"gopkg.in/gomail.v2"
	"io"
)

// EnviarRecibo envia o email com o PDF em Base64 diretamente do Zoho
func EnviarRecibo(emailCliente, nomeCliente, pdfBase64, numeroRecibo string) error {
	m := gomail.NewMessage()

	// Configuração dos cabeçalhos
	m.SetHeader("From", "financeiro@ameliacardoso.com.br")
	m.SetHeader("To", emailCliente)
	m.SetHeader("Subject", fmt.Sprintf("Recibo Nº %s - Confirmado", numeroRecibo))

	// Corpo do email em HTML
	corpoHTML := fmt.Sprintf(`
		<html>
		<body style="font-family: Arial, sans-serif; color: #333;">
			<h2>Olá, %s!</h2>
			<p>Confirmamos o recebimento do seu pagamento.</p>
			<p>O recibo correspondente foi anexado a este e-mail em formato PDF.</p>
		</body>
		</html>
	`, nomeCliente)

	m.SetBody("text/html", corpoHTML)

	// 1. Decodifica a string Base64 para o slice de bytes
	pdfBytes, err := base64.StdEncoding.DecodeString(pdfBase64)
	if err != nil {
		return fmt.Errorf("erro ao decodificar base64 do PDF: %w", err)
	}

	// 2. Anexa os bytes da memória usando a sintaxe correta do Gomail
	nomeArquivo := fmt.Sprintf("recibo_%s.pdf", numeroRecibo)

	m.Attach(nomeArquivo, gomail.SetCopyFunc(func(w io.Writer) error {
		_, err := w.Write(pdfBytes)
		return err
	}))

	// Conexão SMTP com o Zoho
	d := gomail.NewDialer("smtp.zoho.com", 465, "financeiro@ameliacardoso.com.br", "pwd22Adm**")

	// Dispara o e-mail
	if err := d.DialAndSend(m); err != nil {
		return fmt.Errorf("erro ao enviar o e-mail via Zoho: %w", err)
	}

	return nil
}

func main() {
	// Exemplo de uso prático
	stringPdfDoSistema := ""

	err := EnviarRecibo("lavinas@gmail.com", "Fulano de Tal", stringPdfDoSistema, "10254")
	if err != nil {
		fmt.Println("Falha na operação:", err)
		return
	}

	fmt.Println("Recibo enviado com sucesso!")
}
